} StrResult;

StrResult safeReplace(char* s, char* old, char* new) {
    StrResult result;
    if (s == NULL || old == NULL || new == NULL) {
        result.isOk = 0;
        result.data.err.variant = 0;
        result.data.err.data.notFound = "null input";
        return result;
    }

    if (strlen(s) == 0) {
        result.isOk = 0;
        result.data.err.variant = 1;
        result.data.err.data.emptyCollection = 1;
        return result;
    }

    if (strlen(old) == 0) {
        result.isOk = 0;
        result.data.err.variant = 0;
        result.data.err.data.notFound = "empty old string";
        return result;
    }

    char* pos = strstr(s, old);
    if (pos == NULL) {
        result.isOk = 0;
        result.data.err.variant = 0;
        char* msg = malloc(50);
        snprintf(msg, 50, "'%s' not found", old);
        result.data.err.data.notFound = msg;
        return result;
    }

    size_t newLen = strlen(s) - strlen(old) + strlen(new) + 1;
    char* replaced = malloc(newLen);
    if (replaced == NULL) {
        result.isOk = 0;
        result.data.err.variant = 0;
        result.data.err.data.notFound = "memory allocation failed";
        return result;
    }

    size_t prefixLen = pos - s;
    strncpy(replaced, s, prefixLen);
    replaced[prefixLen] = '\0';
    strcat(replaced, new);
    strcat(replaced, pos + strlen(old));

    result.isOk = 1;
    result.data.ok = replaced;
    return result;
}

void freeResult(StrResult r) {
    if (r.isOk) {
        free(r.data.ok);
    } else if (r.data.err.variant == 0) {
        free(r.data.err.data.notFound);
    }
}

