import java.util.*;

public class Solution {
    public static class LookupErr {
        public final String NotFound;
        public final Boolean EmptyCollection;

        private LookupErr(String notFound, Boolean emptyCollection) {
            this.NotFound = notFound;
            this.EmptyCollection = emptyCollection;
        }

        public static LookupErr notFound(String value) {
            return new LookupErr(value, null);
        }

        public static LookupErr emptyCollection() {
            return new LookupErr(null, true);
        }

        @Override
        public String toString() {
            if (NotFound != null) {
                return "NotFound: " + NotFound;
            } else if (EmptyCollection != null) {
                return "EmptyCollection: true";
            }
            return "LookupErr{}";
        }
    }

    public static Object safeReplace(String s, String old, String newStr) {
        if (s == null || old == null || newStr == null) {
            return LookupErr.notFound("null input");
        }

        if (s.isEmpty()) {
            return LookupErr.emptyCollection();
        }

        if (old.isEmpty()) {
            return LookupErr.notFound("empty old string");
        }

        int index = s.indexOf(old);
        if (index < 0) {
            return LookupErr.notFound(old);
        }

        String first = s.substring(0, index);
        String second = s.substring(index + old.length());
        return first + newStr + second;
    }

    public static void main(String[] args) {
        List<TestCase> tests = new ArrayList<>();

        tests.add(new TestCase(
            "hello world", "world", "universe",
            "hello universe"
        ));

        tests.add(new TestCase(
            "banana", "na", "NA",
            "baNAna"
        ));

        tests.add(new TestCase(
            "test", "xyz", "replacement",
            LookupErr.notFound("xyz")
        ));

        tests.add(new TestCase(
            "", "anything", "new",
            LookupErr.emptyCollection()
        ));

        tests.add(new TestCase(
            "multiple words here", " ", "_",
            "multiple_words here"
        ));

        tests.add(new TestCase(
            "edge", "", "middle",
            LookupErr.notFound("empty old string")
        ));

        tests.add(new TestCase(
            "first second third", "second", "2nd",
            "first 2nd third"
        ));

        for (int i = 0; i < tests.size(); i++) {
            TestCase test = tests.get(i);
            Object result = safeReplace(test.s, test.old, test.newStr);

            if (result instanceof String) {
                String expected = (String) test.expected;
                String actual = (String) result;
                System.out.println("Test " + (i + 1) + ": " + 
                    (expected.equals(actual) ? "PASS" : "FAIL") + 
                    " - Result: " + actual);
            } else {
                LookupErr expectedErr = (LookupErr) test.expected;
                LookupErr actualErr = (LookupErr) result;
                System.out.println("Test " + (i + 1) + ": " + 
                    (expectedErr.toString().equals(actualErr.toString()) ? "PASS" : "FAIL") + 
                    " - Result: " + actualErr);
            }
        }
    }

    static class TestCase {
        String s;
        String old;
        String newStr;
        Object expected;

        TestCase(String s, String old, String newStr, Object expected) {
            this.s = s;
            this.old = old;
            this.newStr = newStr;
            this.expected = expected;
        }
    }
}
